    function Get-CloudflareCaFiles {
        <# .SYNOPSIS Substitutes a disposable test anchor only to exercise cryptographic chain logic; real root pins are tested independently above. #>
        param([string]$ScriptRoot)
        return @{ 'origin_ca_rsa_root.crt' = $testAnchorPath; 'origin_ca_ecc_root.crt' = $testAnchorPath }
    }
    $leafRequest = New-Object Security.Cryptography.X509Certificates.CertificateRequest(
        'CN=garage.example.test', $leafRsa, [Security.Cryptography.HashAlgorithmName]::SHA256,
        [Security.Cryptography.RSASignaturePadding]::Pkcs1)
    $san = New-Object Security.Cryptography.X509Certificates.SubjectAlternativeNameBuilder
    $san.AddDnsName('garage.example.test'); $leafRequest.CertificateExtensions.Add($san.Build())
    $signed = $leafRequest.Create($testAnchor, [DateTimeOffset]::Now.AddMinutes(-1), [DateTimeOffset]::Now.AddDays(1), [byte[]]@(1,2,3,4))
    $signedWithKey = [Security.Cryptography.X509Certificates.RSACertificateExtensions]::CopyWithPrivateKey($signed, $leafRsa)
    $accepted = @(Test-HttpsCertificate -Certificate $signedWithKey -Domain 'garage.example.test' -CloudflareProxy -ScriptRoot $root)
    Assert-That ($accepted.Count -eq 0) "Isolated origin chain accepts a matching cryptographic anchor without Windows trust changes ($($accepted -join '; '))"
    $missingKey = @(Test-HttpsCertificate -Certificate $signed -Domain 'garage.example.test' -CloudflareProxy -ScriptRoot $root)
    Assert-That ([bool]($missingKey -match 'no private key')) 'Origin certificate without private key is rejected'
    $expired = $leafRequest.Create($testAnchor, [DateTimeOffset]::Now.AddDays(-1), [DateTimeOffset]::Now.AddMinutes(-1), [byte[]]@(5,6,7,8))
    $expiredWithKey = [Security.Cryptography.X509Certificates.RSACertificateExtensions]::CopyWithPrivateKey($expired, $leafRsa)
    $expiredProblems = @(Test-HttpsCertificate -Certificate $expiredWithKey -Domain 'garage.example.test' -CloudflareProxy -ScriptRoot $root)
    Assert-That ([bool]($expiredProblems -match 'not currently valid') -and [bool]($expiredProblems -match 'chain does not validate')) 'Origin mode does not suppress expiry or other chain errors'
    $clientUses = New-Object Security.Cryptography.OidCollection
    $null = $clientUses.Add((New-Object Security.Cryptography.Oid '1.3.6.1.5.5.7.3.2'))
    $leafRequest.CertificateExtensions.Add((New-Object Security.Cryptography.X509Certificates.X509EnhancedKeyUsageExtension($clientUses, $true)))
    $clientCert = $null; $clientWithKey = $null
    try {
        $clientCert = $leafRequest.Create($testAnchor, [DateTimeOffset]::Now.AddMinutes(-1), [DateTimeOffset]::Now.AddDays(1), [byte[]]@(9,10,11,12))
        $clientWithKey = [Security.Cryptography.X509Certificates.RSACertificateExtensions]::CopyWithPrivateKey($clientCert, $leafRsa)
        Assert-That ([bool](@(Test-HttpsCertificate -Certificate $clientWithKey -Domain 'garage.example.test' -CloudflareProxy -ScriptRoot $root) -match 'chain does not validate')) 'Client-only certificate cannot be used for origin server authentication'
    } finally {
        if ($clientWithKey) { $clientWithKey.Dispose() }
        if ($clientCert) { $clientCert.Dispose() }
    }
} finally {
    Set-Item Function:\Get-CloudflareCaFiles -Value $originalCaFiles
    foreach ($certObject in @($testAnchor, $signed, $signedWithKey, $expired, $expiredWithKey)) {
        if ($certObject) { $certObject.Dispose() }
    }
    $rootRsa.Dispose(); $leafRsa.Dispose()
    if (Test-Path -LiteralPath $testAnchorPath) { Remove-Item -LiteralPath $testAnchorPath -Force }
}
$originalNative = (Get-Item Function:\Invoke-Native).ScriptBlock
$script:tlsCalls = @()
$script:omitRay = $false
$script:localTlsFailure = $false
try {
    function Invoke-Native {
        <# .SYNOPSIS Captures TLS invocations without networking, IIS changes or certificate imports. #>
        param([string]$FilePath, [string[]]$Arguments, [switch]$AllowFailure)
        $script:tlsCalls += ,$Arguments
        if ($Arguments -contains '--resolve') {
            return [pscustomobject]@{ ExitCode = $(if ($script:localTlsFailure) { 60 } else { 0 }); Output = @('{"status":"ok"}') }
        }
        if ($Arguments -contains '--write-out') { return [pscustomobject]@{ ExitCode = 0; Output = @('400') } }
        return [pscustomobject]@{ ExitCode = 0; Output = @(
            $(if ($script:omitRay) { 'Server: other' } else { 'CF-Ray: fixture' }), '{"status":"ok"}'
        ) }
    }
    $tlsCfg = [pscustomobject]@{ Domain = 'example.test'; ScriptRoot = $root; CloudflareProxy = $true }
    Test-PublicHttps -Config $tlsCfg
    Assert-That ($script:tlsCalls[0] -contains '--cacert' -and $script:tlsCalls[0] -contains $caFiles['origin_ca_bundle.crt']) 'Local origin TLS uses pinned CA bundle without disabling verification'
    Assert-That ($script:tlsCalls[1] -notcontains '--cacert' -and $script:tlsCalls[1] -contains '--dump-header') 'Public edge TLS retains normal public trust'
    $script:omitRay = $true
    try { Test-PublicHttps -Config $tlsCfg; Assert-That $false 'Cloudflare mode rejects a missing public proxy header' }
    catch { Assert-That ($_.Exception.Message -match 'CF-Ray') 'Cloudflare mode rejects a missing public proxy header' }
    $script:omitRay = $false; $script:localTlsFailure = $true
    try { Test-PublicHttps -Config $tlsCfg; Assert-That $false 'Local TLS failure is never ignored' }
    catch { Assert-That ($_.Exception.Message -match 'FAILED') 'Local TLS failure is never ignored' }
    $script:localTlsFailure = $false; $script:tlsCalls = @(); $tlsCfg.CloudflareProxy = $false
    Test-PublicHttps -Config $tlsCfg
    Assert-That ($script:tlsCalls[0] -notcontains '--cacert') 'Direct IIS verification remains on ordinary system trust'
} finally { Set-Item Function:\Invoke-Native -Value $originalNative }

$ps = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
$check = & $ps -NoProfile -NonInteractive -File $self -Mode Check 2>&1 | Out-String
Assert-That ($check -match 'Check \(read-only\)' -and $check -match 'Nothing was changed') 'Mode Check runs read-only'
$whatIf = & $ps -NoProfile -NonInteractive -File $self -Mode All -WhatIf 2>&1 | Out-String
Assert-That ($whatIf -notmatch 'New Alias|Import-Module') 'WhatIf output contains no module/alias mutation noise'
Assert-That ($whatIf -match 'What if' -and $whatIf -match 'Idempotently create roles' -and $whatIf -match 'Gradle assembleRelease' -and $whatIf -notmatch 'Approval required') 'Mode All -WhatIf lists changes and never prompts'
$cfWhatIf = & $ps -NoProfile -NonInteractive -File $self -Mode Deploy -CloudflareProxy -ApiPort 3100 -WhatIf 2>&1 | Out-String
Assert-That ($cfWhatIf -match 'What if' -and $cfWhatIf -notmatch 'Approval required|integrity check failed') 'Cloudflare Deploy preview remains non-mutating'

Write-Host "`n$script:passes passed, $script:failures failed."
if ($script:failures) { exit 1 } else { exit 0 }
